// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;
    function setUp() public { c = new PRIVATE_ETH_CELL(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, type(uint256).max);

        RevertingLog rl = new RevertingLog();

        c.SetLogFile(address(rl));

        vm.deal(actor, amount);

        bool ok;
        vm.prank(actor);
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract RevertingLog {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    fallback() external payable {}
    function AddMessage(address, uint, string memory) public pure {
        revert("log revert");
    }
}
